Object.assign(S.cs,{mDesc:{pent:'<b>Pentatonika</b> = 5 tónů, které nad písničkou skoro nikdy nezní špatně. Začni s ní.',scale:'<b>Stupnice</b> = pentatonika + 2 tóny navíc. Zní pestřeji, ty dva tóny ale hraj jen na chvilku.',chord:'<b>Tóny akordu</b> = tóny, ze kterých je akord, který právě hraje. Na ně přistávej, zní nejjistěji. Akord vybereš v Rozboru.'},
sgT:'Jak na sólo v téhle písničce',sgShow:'Ukaž',sgHear:'Poslechni pentatoniku',sgJam:'Zkus to s doprovodem',sgLes:'Lekce improvizace',
sg1T:'Najdi domov.',sg1:(k,h)=>`Písnička je v tónině <b>${k}</b>. Domov je tón <b>${h}</b>: na něm fráze zní uzavřeně, jako tečka za větou.`,
sg2T:'Hraj pentatoniku.',sg2:(n,f,rel)=>`Tóny <b>${n}</b>. Box začíná na <b>${f}. pražci</b> basové E struny (na hmatníku je zvýrazněný).${rel?` Je to stejný tvar jako ${rel} moll pentatonika, to je v pořádku: dur a jeho paralelní moll mají stejné tóny.`:''} Nad celou písničkou zní dobře, takže se nemusíš bát.`,
sg3T:'Přidej koření.',sg3:e=>`Stupnice má navíc tóny <b>${e}</b>. Zní zajímavěji, ale jsou „ostřejší“: zahraj je jen projetím, nezůstávej na nich.`,
sg4T:'Míř na tóny akordu.',sg4:'Když se změní akord, zahraj jeden z jeho tónů. Tím sólo „sedí“ na doprovodu:',
sg5T:'Recept:',sg5:h=>`krátká fráze z pentatoniky → pauza → na změně akordu přistaň na jeho tónu → na konci se vrať na <b>${h}</b>. Začni klidně jen se 3 tóny a hraj pomalu.`});
